head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf35000";
scwin.frm = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_isuStartDate();
        scwin.init_datefmt_cal_isuEndDate();
        scwin.init_datefmt_cal_listStartDate();
        scwin.init_datefmt_cal_listEndDate();
        scwin.init_datefmt_cal_grntStartDate();
        scwin.init_datefmt_cal_grntEndDate();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf35000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_isuStartDate", fn: function () { return String((dma_pageContext.get("isuStartDate") ?? "")); } },
        { childId: "cal_isuEndDate", fn: function () { return String((dma_pageContext.get("isuEndDate") ?? "")); } },
        { childId: "cal_listStartDate", fn: function () { return String((dma_pageContext.get("listStartDate") ?? "")); } },
        { childId: "cal_listEndDate", fn: function () { return String((dma_pageContext.get("listEndDate") ?? "")); } },
        { childId: "cal_grntStartDate", fn: function () { return String((dma_pageContext.get("grntStartDate") ?? "")); } },
        { childId: "cal_grntEndDate", fn: function () { return String((dma_pageContext.get("grntEndDate") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_isuStartDate
 * @description 초기화 — datefmt cal isu Start Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_isuStartDate = function () { $c.date.checkCalendarFormat("cal_isuStartDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_isuEndDate
 * @description 초기화 — datefmt cal isu End Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_isuEndDate = function () { $c.date.checkCalendarFormat("cal_isuEndDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_listStartDate
 * @description 초기화 — datefmt cal list Start Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_listStartDate = function () { $c.date.checkCalendarFormat("cal_listStartDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_listEndDate
