/**
 * @method
 * @name init_datefmt_cal_grntEndDate
 * @description 초기화 — datefmt cal grnt End Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_grntEndDate = function () { $c.date.checkCalendarFormat("cal_grntEndDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

