    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf35000.btn_search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/main/eng.do?method=eng_isurSrch",
        ref: "dma_searchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_download
 * @description download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_download = async function () {
    try { return await $c.data.downFile("/jsp/common/down.jsp", "", ($c.util.getComponent("dma_downloadReq") ? $c.util.getComponent("dma_downloadReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name SetChecked
 * @description Set Checked 처리
 * @param {*} fm fm
 * @returns {void}
 * @hidden N
 */
scwin.SetChecked = function (fm) {
    if ((String($c.util.getComponent('ipt_checkBox').getValue() || "") !== "")) {
        $c.util.getComponent("ipt_chkKind02").setValue(true);
        $c.util.getComponent("ipt_chkKind03").setValue(true);
        $c.util.getComponent("ipt_chkKind05").setValue(true);
        $c.util.getComponent("ipt_chkKind07").setValue(true);
        $c.util.getComponent("ipt_chkKind08").setValue(true);
        $c.util.getComponent("ipt_chkKind09").setValue(true);
        $c.util.getComponent("ipt_chkKind10").setValue(true);
        $c.util.getComponent("ipt_chkKind11").setValue(true);
        $c.util.getComponent("ipt_chkKind12").setValue(true);
        $c.util.getComponent("ipt_chkKind13").setValue(true);
        $c.util.getComponent("ipt_chkKind14").setValue(true);
    } else {
        $c.util.getComponent("ipt_chkKind02").setValue(false);
        $c.util.getComponent("ipt_chkKind03").setValue(false);
        $c.util.getComponent("ipt_chkKind05").setValue(false);
        $c.util.getComponent("ipt_chkKind07").setValue(false);
        $c.util.getComponent("ipt_chkKind08").setValue(false);
        $c.util.getComponent("ipt_chkKind09").setValue(false);
        $c.util.getComponent("ipt_chkKind10").setValue(false);
        $c.util.getComponent("ipt_chkKind11").setValue(false);
        $c.util.getComponent("ipt_chkKind12").setValue(false);
        $c.util.getComponent("ipt_chkKind13").setValue(false);
        $c.util.getComponent("ipt_chkKind14").setValue(false);
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const fm = (document.JLDINF35000 || { elements: [] });
    const send = false;
    const check = scwin.checkebox(fm);
    let kind = "";
    if (!check) {
        $c.util.getComponent("ipt_checkBox").setValue(true);
        scwin.SetChecked(fm);
    }
    if (($c.util.getComponent('ipt_searchWord').getValue() == null ? '' : String($c.util.getComponent('ipt_searchWord').getValue())) === '' && ($c.util.getComponent('ipt_comEngNm').getValue() == null ? '' : String($c.util.getComponent('ipt_comEngNm').getValue())) === '' && ($c.util.getComponent('ipt_isurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_isurCd').getValue())) === '' && ($c.util.getComponent('cal_isuStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_isuStartDate').getValue())) === '' && ($c.util.getComponent('cal_isuEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_isuEndDate').getValue())) === '' && ($c.util.getComponent('cal_listStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_listStartDate').getValue())) === '' && ($c.util.getComponent('cal_listEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_listEndDate').getValue())) === '' && ($c.util.getComponent('cal_grntStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_grntStartDate').getValue())) === '' && ($c.util.getComponent('cal_grntEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_grntEndDate').getValue())) === '') {
        await $c.win.alert("Please, enter ISIN Number/Company Desc./Date Desc. in text boxes.");
        $c.util.getComponent("ipt_searchWord").focus();
        return;
    }
    if ((($c.util.getComponent('cal_isuStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_isuStartDate').getValue())) !== '' || ($c.util.getComponent('cal_isuEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_isuEndDate').getValue())) !== '') && (($c.util.getComponent('cal_isuStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_isuStartDate').getValue())) === '' || ($c.util.getComponent('cal_isuEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_isuEndDate').getValue())) === '')) {
        let tmpObj = scwin.findNullObj("isuStartDate", "isuEndDate");
        await $c.win.alert("Please, enter Issuing date in text boxes.");
        tmpObj.focus();
        return;
    }
    if ((($c.util.getComponent('cal_listStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_listStartDate').getValue())) !== '' || ($c.util.getComponent('cal_listEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_listEndDate').getValue())) !== '') && (($c.util.getComponent('cal_listStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_listStartDate').getValue())) === '' || ($c.util.getComponent('cal_listEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_listEndDate').getValue())) === '')) {
        tmpObj = scwin.findNullObj("listStartDate", "listEndDate");
        await $c.win.alert("Please, enter Listed date in text boxes.");
        tmpObj.focus();
        return;
    }
    if ((($c.util.getComponent('cal_grntStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_grntStartDate').getValue())) !== '' || ($c.util.getComponent('cal_grntEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_grntEndDate').getValue())) !== '') && (($c.util.getComponent('cal_grntStartDate').getValue() == null ? '' : String($c.util.getComponent('cal_grntStartDate').getValue())) === '' || ($c.util.getComponent('cal_grntEndDate').getValue() == null ? '' : String($c.util.getComponent('cal_grntEndDate').getValue())) === '')) {
        tmpObj = scwin.findNullObj("grntStartDate", "grntEndDate");
        await $c.win.alert("Please, enter ISIN Allocated date in text boxes.");
        tmpObj.focus();
        return;
    }
    if ((String($c.util.getComponent('ipt_chkKind02').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind02').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind03').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind03').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind05').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind05').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind07').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind07').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind08').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind08').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind09').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind09').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind10').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind10').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind11').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind11').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind12').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind12').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind13').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind13').getValue();
    }
    if ((String($c.util.getComponent('ipt_chkKind14').getValue() || "") !== "")) {
        kind += $c.util.getComponent('ipt_chkKind14').getValue();
    }
    $c.util.getComponent('dma_searchReq').set('kind', kind);
    fm.action = "/main/eng.do?method=eng_isurSrch";
    blockLoading();
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name findNullObj
 * @description find Null Obj 처리
 * @param {*} sId1 sId1
 * @param {*} sId2 sId2
 * @returns {void}
 * @hidden N
 */
scwin.findNullObj = function (sId1, sId2) {
    if ($("#" + sId1).val() === "") {
        return $("#" + sId1)[0];
    }
    if ($("#" + sId2).val() === "") {
        return $("#" + sId2)[0];
    }
};

