        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind07').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind08').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind09').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind10').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind11').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind12').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind13').getValue() || "") !== "")) {
        check = true;
    }
    if ((String($c.util.getComponent('ipt_chkKind14').getValue() || "") !== "")) {
        check = true;
    }
    return check;
};

/**
 * @method
 * @name download
 * @description download 처리
 * @param {*} nm nm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function (nm) {
    scwin.frm = (document.form || { elements: [] });
    $c.util.getComponent('ipt_filename').setValue(nm);
    scwin.frm.action = "/jsp/common/down.jsp";
    await scwin.tx_download();
};

/**
 * @method
 * @name Chk_Date
 * @description Chk Date 처리
 * @param {*} Name Name
 * @param {String} Date_Str Date_Str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_Date = async function (Name, Date_Str) {
    let sdate = Name.getValue(); if (sdate == null) { sdate = ''; }
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '-' + pmonth + '-' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate !== "" && (syear !== soyear || smonth !== somonth || sday !== soday)) {
        await $c.win.alert("입력한 " + Date_Str + "이 올바르지 않습니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate !== "" && sdate.length !== 8) {
        await $c.win.alert("입력한 " + Date_Str + "이 8자리가 아닙니다. \n");
        (Name && Name.setFocus ? Name.setFocus() : (Name && Name.focus ? Name.focus() : void 0));
        return false;
    }
    if (sdate === "") {
        Name.setValue('');
    } else {
        Name.setValue(sdate);
    }
    return true;
};
